instance.invitation-mail:
invitation -> applicationName -> link -> subject -> body -> {
  mailBody = $body.fill($applicationName, $link).localize();
  mailSubject = $subject.fill($applicationName).localize();
  emailAddr = $invitation.get(`tl.security.selfservice:Invitation#email`);

  try(
    sendMail(
      subject: $mailSubject,
      to: $emailAddr,
      body: binary(name: "mail.html", contentType: "text/html", encoding: "utf-8", data: $mailBody)
    ),
    catch: mailError -> {
      log("Sending mail to {0} failed. reason: {1}", $emailAddr, $mailError, level: "warn");
      false
    }
  );
}

