self-registration.registration-mail:
email -> applicationName -> code -> {
  emailBody = #"tl.security.selfservice.mail.registration.body".fill($applicationName, $code).localize();
  subject = #"tl.security.selfservice.mail.registration.subject".fill($applicationName).localize();
  emailAddr = $email;

  try(
    sendMail(
      subject: $subject,
      to: $emailAddr,
      body: binary(name: "mail.html", contentType: "text/html", encoding: "utf-8", data: $emailBody)
    ),
    catch: mailError -> {
      info("Sending mail to " + $emailAddr + " failed. reason: " + $mailError);
      false
    }
  );
}

